/* Service worker: keeps the app available offline. Generated by scripts/build.ts. */
const VERSION = "__VERSION__";
const ASSETS = __ASSETS__;
const CACHE = "rummy-trainer-" + VERSION;

self.addEventListener("install", event => {
    // bypass the HTTP cache, so that exactly the files of this version are stored
    const requests = ASSETS.map(url => new Request(url, { cache: "reload" }));
    event.waitUntil(caches.open(CACHE).then(cache => cache.addAll(requests)).then(() => self.skipWaiting()));
});

self.addEventListener("activate", event => {
    event.waitUntil(
        caches.keys()
            .then(keys => Promise.all(keys.filter(key => key.startsWith("rummy-trainer-") && key !== CACHE).map(key => caches.delete(key))))
            .then(() => self.clients.claim()),
    );
});

/** A redirected response can't answer a navigation, so it is copied into a plain one. */
function unredirected(response) {
    if (!response.redirected) return response;
    return new Response(response.body, { status: response.status, statusText: response.statusText, headers: response.headers });
}

// Network first: online, the page and all its files come from the current version (a cached
// stylesheet next to a new page breaks the layout); the cache is only used offline.
self.addEventListener("fetch", event => {
    const request = event.request;
    if (request.method !== "GET" || new URL(request.url).origin !== self.location.origin) return;
    const navigation = request.mode === "navigate";
    const key = navigation ? "./" : request;
    event.respondWith(
        fetch(navigation ? request.url : request, { cache: "no-cache" })
            .then(response => {
                if (response.ok && response.type === "basic") {
                    const copy = response.clone();
                    event.waitUntil(caches.open(CACHE).then(cache => cache.put(key, copy)));
                }
                return unredirected(response);
            })
            .catch(() => caches.match(key).then(cached => cached || Response.error())),
    );
});
